const step=(title,text,formula='')=>({title,text,formula});
const s=(id,year,date,era,title,question,body,artifact,insight,steps,source,link)=>({id,year,date,era,title,question,body,artifact,insight,steps,source,link});
export const stations=[
s('markov',1906,'1906','Вероятность и вычисление','Будущее — через вероятности','Можно ли описать сложное поведение без полного набора правил?','Марковские цепи предлагают компактную модель последовательности: распределение следующего состояния зависит от текущего. Это ещё не машинное обучение в современном смысле, но важный математический язык для последовательностей и принятия решений.','Три состояния, соединённые возможными переходами. Вероятности разобраны на диаграмме.','Вместо единственного предписанного ответа — распределение возможных продолжений.',[
step('Состояние вместо всей истории','В простейшей цепи первого порядка текущее состояние содержит всю информацию из прошлого, нужную для предсказания следующего. Это предположение модели, а не универсальный закон природы.',"P(s_{t+1}\\mid s_t,\\ldots,s_0) = P(s_{t+1}\\mid s_t)"),step('Матрица переходов','Каждая строка матрицы — распределение следующего состояния. В учебном примере: из A цепь остаётся в A с вероятностью 0.6, переходит в B с 0.3 и в C с 0.1. Сумма строки равна единице.',"\\boldsymbol{\\pi}_{t+1}=\\boldsymbol{\\pi}_t P"),step('Связь с будущим ML','В скрытых марковских моделях состояние не наблюдается напрямую; в марковских процессах принятия решений переходы зависят ещё и от действия. Отсюда протянется линия к распознаванию последовательностей и RL.')],'Основа: марковские цепи; числовой пример — авторский',''),
s('neuron',1943,'1943–1949','Вероятность и вычисление','Нейрон как вычислительный элемент','Как из простых элементов получить сложное вычисление?','Маккаллок и Питтс рассматривают пороговые элементы и логические вычисления в сетях. Хебб позднее связывает обучение с изменением силы связей. Здесь встречаются две идеи: структура сети вычисляет, а изменение связей позволяет учиться.','Пороговый нейрон: входы сходятся в сумматор, затем сигнал проходит порог.','Нейрон — математическое упрощение, а не точная копия биологической клетки.',[
step('Входы собираются вместе','В современной записи входы x умножаются на веса w. Сумматор и смещение b задают линейную комбинацию. Оригинальная модель 1943 года была логической и не содержала современного алгоритма обучения.',"z=\\sum_i w_i x_i+b"),step('Порог создаёт решение','Ступенчатая функция выдаёт 1, когда сумма достигает порога. Один такой элемент отделяет классы гиперплоскостью; композиция элементов позволяет строить более сложные функции.',"\\hat y=\\mathbf{1}[z\\geq 0]"),step('Обучение меняет связи','Хеббовская идея связывает укрепление связи с совместной активностью. Позднее появятся другие правила изменения весов, включая обучение по ошибке и градиентный спуск.')],'McCulloch & Pitts · 1943; Hebb · 1949',''),
s('theseus',1950,'1948–1950','Вероятность и вычисление','Машина, которую можно обучить','Что, если не программировать интеллект целиком?','Тьюринг обсуждает обучаемую машину. В устройстве Theseus Шеннона электромеханическая мышь исследует лабиринт; релейная система сохраняет найденные направления. Опыт меняет последующее поведение.','Рельефный лабиринт, мышь и светящийся найденный маршрут.','Память о результате поиска уже полезна, даже без современной нейросети.',[
step('Исследовать неизвестное','До нахождения цели устройство пробует направления. Структура лабиринта ограничивает действия; тупики заставляют возвращаться. В сцене показана авторская схема, не точная реконструкция устройства.'),step('Сохранить найденный путь','Релейная память фиксирует полезные направления. При повторном запуске мышь использует накопленную информацию и проходит маршрут эффективнее.'),step('От устройства к программе исследований','Тьюринг ставит более общий вопрос: можно ли создать обучаемую систему и воспитывать её, вместо того чтобы вручную перечислять все разумные действия?')],'Turing · Computing Machinery and Intelligence, 1950','https://academic.oup.com/mind/article/LIX/236/433/986238'),
s('dartmouth',1956,'1955–1956','Рождение дисциплины','Интеллект становится исследовательской программой','Что объединяет язык, рассуждение, обучение и восприятие?','Дартмутское предложение 1955 года вводит название artificial intelligence; летняя встреча проходит в 1956-м. Это объединение вопросов под одной программой, а не появление готовой технологии.','Исследовательский стол и четыре направления, расходящиеся от общего центра.','AI — широкая цель. ML — один из способов приблизиться к ней.',[
step('Символическая линия','Описывать знания символами, а рассуждение — правилами преобразования. Явная структура делает вывод прозрачным, но требует формализовать знания.'),step('Обучаемая линия','Подбирать поведение по примерам и опыту. Правила не исчезают: исследователь выбирает представление, модель и обучающий сигнал.'),step('Разные подходы сосуществуют','Поиск, логика, вероятностные модели и нейросети развиваются параллельно. Их последующее сочетание важнее простой истории смены одного подхода другим.')],'McCarthy, Minsky, Rochester, Shannon · Dartmouth proposal','http://www-formal.stanford.edu/jmc/history/dartmouth/dartmouth.html'),
s('perceptron',1958,'1957–1959','Обучение и его границы','Исправлять веса по ошибкам','Как превратить набор примеров в правило решения?','Перцептрон Розенблатта корректирует веса после неправильного ответа. Программа Сэмюэла для шашек использует опыт игры. На первый план выходит изменение модели через данные, а не только запись готовых правил.','Сенсорная матрица, взвешенные соединения и один выходной элемент.','Однослойный перцептрон обучаем, но его граница решения остаётся линейной.',[
step('Сделать предсказание','Вход проходит через взвешенную сумму и порог. Каждый вес задаёт вклад признака. Положение разделяющей прямой зависит от весов и смещения.',"\\hat y=\\mathbf{1}[\\mathbf w^{\\mathsf T}\\mathbf x+b\\geq 0]"),step('Исправить ошибку','Если ответ неверен, веса сдвигаются в направлении, которое помогает правильно классифицировать данный пример. Для линейно разделимых данных классическое правило сходится.',"\\mathbf w\\leftarrow\\mathbf w+\\eta(y-\\hat y)\\mathbf x"),step('Увидеть ограничение на XOR','В XOR одинаковые входы относятся к одному классу, разные — к другому. Одной прямой их не разделить. Нужны промежуточные нелинейные признаки или несколько слоёв.')],'Rosenblatt · The Perceptron, 1958',''),
s('learning',1960,'Понятие ML','Обучение и его границы','Что именно значит «учиться»','Откуда модель получает сигнал для изменения параметров?','Модель — семейство функций с настраиваемыми параметрами. Обучение выбирает параметры по данным или опыту. Вывод применяет уже настроенную функцию к новому входу. Это общий каркас для очень разных методов.','Две линии: поток обучающих примеров и поток новых входов.','Архитектура отвечает на вопрос «чем вычислять», обучающий сигнал — «чему учиться».',[
step('С учителем','У обучающих примеров есть целевой ответ: класс, число или последовательность. Предсказание сравнивается с целью, и параметры обновляются. На новых объектах правильный ответ заранее неизвестен.'),step('Без учителя и self-supervised','Можно искать структуру без целевых ответов. В self-supervised обучении цель конструируют из самих данных: скрывают слово, зашумляют изображение или сопоставляют два вида одного объекта.'),step('С подкреплением','Система действует, получает новые наблюдения и награду. Сигнал может быть отложенным: нужно понять, какие ранние действия привели к результату. Это отличается от готовой пары «вход — верный ответ».')],'Три семейства обучающих сигналов; концептуальная схема',''),
s('winter',1974,'1969–1993','Обучение и его границы','Ожидания опережают возможности','Почему обещания общего интеллекта сменились «зимами»?','Ограниченность алгоритмов, вычислений и данных сталкивается с завышенными ожиданиями. Позднее экспертные системы упираются в стоимость извлечения и поддержки знаний. При этом теория обучения и отдельные методы продолжают развиваться.','Архив правил и две зоны затухания на исторической линии.','Спад интереса к AI не означает остановку исследований машинного обучения.',[
step('Первая зима · примерно 1974–1980','Критика результатов и сокращение финансирования; отчёт Лайтхилла 1973 года — одна из вех. Книга Минского и Пейперта 1969 года анализирует ограничения перцептронов, но не является единственной причиной спада.'),step('Бум экспертных систем','Знания переводятся в правила «если — то». В узких областях это работает, но большие базы правил трудно обновлять и согласовывать: возникает bottleneck приобретения знаний.'),step('Вторая зима · примерно 1987–1993','Кризис коммерческих ожиданий и специализированного оборудования. Статистические методы и нейросети продолжают развиваться. Даты условны и зависят от страны и направления.')],'Исторические интервалы условны; хронология по исходному черновику',''),
s('energy',1982,'1982–1985','Представления и оптимизация','Память как минимум энергии','Как восстановить целое по неполному образу?','В сети Хопфилда сохранённые образы соответствуют устойчивым состояниям. Обновление элементов может уменьшать энергию и приводить искажённый вход к одному из этих состояний. Машины Больцмана добавляют вероятностное описание и скрытые переменные.','Энергетическая поверхность с несколькими впадинами и траекторией состояния.','Физическая метафора становится математическим механизмом модели.',[
step('Состояния и симметричные связи','У классической сети Хопфилда бинарные состояния, симметричные веса и отсутствуют связи узла с самим собой. Энергия связывает состояние всей системы с её параметрами.',"\\begin{aligned}E(\\mathbf s)&=-\\frac12\\sum_{i,j}w_{ij}s_i s_j\\\\&\\quad+\\sum_i\\theta_i s_i\\end{aligned}"),step('Спуск к устойчивому образу','При стандартном асинхронном обновлении энергия не возрастает. Но можно попасть в нежелательный локальный минимум; объём памяти ограничен.'),step('От минимумов к распределениям','В машине Больцмана низкоэнергетические состояния вероятнее, но не единственно возможны. Обучение меняет ландшафт, чтобы данные получали большую вероятность.',"p(\\mathbf s)\\propto\\exp[-E(\\mathbf s)]")],'Hopfield · 1982; Ackley, Hinton, Sejnowski · 1985',''),
s('backprop',1986,'1970–1986','Представления и оптимизация','Производные проходят назад','Как понять вклад каждого веса в общую ошибку?','Обратный режим автоматического дифференцирования применяет цепное правило к вычислительному графу. Backprop делает этот механизм рабочим способом обучения многослойных сетей. Важнейшая идея — переиспользовать промежуточные производные.','Многослойный граф: бирюзовый прямой проход и коралловый обратный.','Обратный проход вычисляет градиенты; шаг оптимизатора затем меняет параметры.',[
step('Прямой проход','Сначала вычисляются активации и ошибка. Учебный скалярный пример: x = 2, w₁ = 0.5, w₂ = 1.5, цель y = 2. ReLU активна: h = 1, ŷ = 1.5, L = 0.125.',"\\begin{aligned}h&=\\operatorname{ReLU}(w_1x)\\\\\\hat y&=w_2h\\\\L&=\\tfrac12(\\hat y-y)^2\\end{aligned}"),step('Цепное правило','На выходе ∂L/∂ŷ = −0.5. Для второго веса: −0.5 × h = −0.5. Для первого: −0.5 × w₂ × 1 × x = −1.5. Один обратный проход даёт оба градиента.',"\\frac{\\partial L}{\\partial w_1}=\\frac{\\partial L}{\\partial\\hat y}\\frac{\\partial\\hat y}{\\partial h}\\frac{\\partial h}{\\partial w_1}"),step('Шаг обучения','При η = 0.1 новые веса равны 0.65 и 1.55. Эта конкретная ошибка уменьшается; поведение на новых данных ещё нужно обеспечить обобщением.',"\\mathbf w\\leftarrow\\mathbf w-\\eta\\nabla_{\\mathbf w}L"),step('Историческая связь','Ранние корни — reverse-mode AD и работы Линнайнмаа; Вербос применяет идеи к обучению сетей. Работа Румельхарта, Хинтона и Уильямса 1986 года широко распространяет backprop. Позже этот же autodiff станет основой PINN.')],'Rumelhart, Hinton & Williams · 1986','https://www.nature.com/articles/323533a0'),
s('cnn',1989,'1980–1998','Представления и оптимизация','Зрение строится из локальных признаков','Как учесть, что один и тот же контур встречается в разных местах?','Neocognitron Фукусимы предвосхищает иерархию локальных признаков. LeCun и коллеги обучают свёрточные сети через backprop: почтовые индексы в 1989 году, LeNet-5 в 1998-м.','Стопка карт признаков: от пиксельного изображения к небольшим абстрактным слоям.','Свёртка разделяет веса между позициями, а глубина строит иерархию.',[
step('Один фильтр — много позиций','Ядро 3 × 3 проходит по изображению. В каждой позиции одни и те же девять весов умножаются на локальные пиксели. Получается карта откликов одного признака.',"y_{ij}=\\sum_{a,b}k_{ab}\\,x_{i+a,j+b}"),step('От карт к иерархии','Несколько фильтров дают несколько каналов. Нелинейность и уменьшение пространственного размера позволяют следующим слоям собирать более крупные комбинации признаков.'),step('LeNet-5 как конкретный пример','Классическая схема: 32 × 32 → C1: 6 × 28 × 28 → S2: 6 × 14 × 14 → C3: 16 × 10 × 10 → S4: 16 × 5 × 5 → C5: 120 → F6: 84 → 10 выходов. Исторические детали связности и выходного слоя здесь упрощены.')],'LeCun et al. · Gradient-Based Learning Applied to Document Recognition','http://yann.lecun.com/exdb/publis/pdf/lecun-98.pdf'),
s('generalize',1995,'1960-е–2000-е','Представления и оптимизация','Запомнить — ещё не обобщить','Почему модель должна работать на невиданных примерах?','Теория Вапника–Червоненкиса связывает сложность класса функций, объём данных и обобщение. SVM, деревья, ансамбли и вероятностные методы формируют сильную статистическую традицию — она не исчезает с появлением deep learning.','Два облака точек и разделяющая поверхность с полосой запаса.','Полезная модель переносит закономерность, а не воспроизводит шум выборки.',[
step('Выбрать семейство функций','Более гибкая модель может точнее описать обучающие точки, включая случайный шум. Само по себе идеальное совпадение с выборкой не говорит о качестве на новых объектах.'),step('Задать предпочтение','Например, SVM ищет разделение с большим зазором; регуляризация ограничивает сложность. Нелинейные ядра позволяют работать с более сложными границами.'),step('Несколько способов выразить структуру','Деревья разбивают пространство признаков, ансамбли объединяют модели, нейросети учат представления. Это разные предположения о данных, а не лестница от «устаревшего» к «правильному».')],'Cortes & Vapnik · Support-Vector Networks, 1995','https://link.springer.com/article/10.1007/BF00994018'),
s('alexnet',2012,'2009–2012','Прорыв масштаба','Три линии встречаются в одной точке','Что изменилось, если нейросети существовали давно?','Большой размеченный ImageNet, доступные вычисления на GPU и эффективные приёмы обучения сходятся в AlexNet. Прорыв показывает, что обучаемые представления можно масштабировать на сложное распознавание изображений.','Графический процессор, массив данных и глубокая свёрточная башня.','Прорыв возник из сочетания алгоритмов, данных и вычислений.',[
step('Данные задают масштаб','ImageNet опубликован в 2009 году. В задаче ILSVRC 2012 используется примерно 1.2 млн обучающих изображений и 1000 категорий. Большой корпус делает обучение богатых представлений практическим.'),step('Архитектура и оптимизация','AlexNet: пять свёрточных и три полносвязных слоя; ReLU, data augmentation и dropout в полносвязной части. Сеть обучалась на двух GPU.'),step('Меняется способ строить системы','Вместо отдельного конструирования признаков и классификатора всё больше задач решают сквозным обучением. Следующий вопрос: можно ли не только распознавать, но и моделировать распределение данных?')],'Krizhevsky, Sutskever & Hinton · 2012','https://papers.nips.cc/paper/4824-imagenet-classification-with-deep-convolutional-neural-networks'),
s('embedding',2013,'2013','Представления становятся пространствами','Значение как положение в пространстве','Что модель хранит вместо символа или категории?','Word2Vec учит векторы слов через задачу предсказания контекста. Близость векторов возникает из статистики употребления. Идея обучаемого представления затем становится общей для текста, изображений и других модальностей.','Облако точек с локальными группами и направлениями между ними.','Эмбеддинг — не готовый словарь смысла, а представление, зависящее от задачи обучения.',[
step('Из индекса в вектор','Таблица эмбеддингов сопоставляет каждому токену строку чисел. Она обучается вместе с предсказательной задачей; one-hot индекс выбирает строку таблицы.'),step('Контекст даёт обучающий сигнал','В skip-gram центральное слово предсказывает соседние. Похожие контексты создают похожие направления в пространстве; конкретная геометрия зависит от данных и обучения.'),step('От статического к контекстному','В Word2Vec слово имеет один вектор. В Transformer представление токена обновляется с учётом окружающих токенов: одно слово может получать разные представления в разных фразах.')],'Mikolov et al. · Efficient Estimation of Word Representations','https://arxiv.org/abs/1301.3781'),
s('vae',2013,'2013 / 2014','Генеративное моделирование','VAE: распределение вместо единственного кода','Как сделать скрытое пространство пригодным для генерации?','Обычный автоэнкодер учится восстанавливать вход через узкий код. VAE задаёт вероятностную латентную модель и обучаемое приближение к распределению скрытого кода. Это позволяет сочетать восстановление и генерацию новых образцов.','Две воронки вокруг облака латентных состояний: кодирование и декодирование.','Декодер учится превращать скрытый код в данные; регуляризация организует пространство кодов.',[
step('Encoder выдаёт параметры распределения','Для входа x кодировщик предсказывает μ(x) и log σ²(x). В типичном VAE это параметры диагонального нормального qφ(z|x), а не единственный вектор.',"q_\\phi(z\\mid x)=\\mathcal N\\!\\left(\\mu(x),\\operatorname{diag}\\sigma^2(x)\\right)"),step('Случайность отделяется от параметров','Берём ε из стандартной нормали и строим z = μ + σ ⊙ ε. Теперь градиент может проходить через μ и σ, хотя код остаётся случайным.',"\\begin{aligned}\\varepsilon&\\sim\\mathcal N(0,I)\\\\z&=\\mu+\\sigma\\odot\\varepsilon\\end{aligned}"),step('Два требования к обучению','Декодер должен хорошо объяснять x, а qφ(z|x) — не уходить произвольно далеко от выбранного prior p(z). Обычно оптимизируют отрицательную ELBO.',"\\begin{aligned}L={}&-\\mathbb E_{q_\\phi(z\\mid x)}[\\log p_\\theta(x\\mid z)]\\\\&+D_{\\mathrm{KL}}\\!\\left(q_\\phi(z\\mid x)\\,\\|\\,p(z)\\right)\\end{aligned}"),step('Генерация не требует encoder','Для нового образца берут z ∼ p(z) и пропускают через decoder. Кодировщик нужен для обучения и кодирования наблюдаемых данных. Предпечатная работа — 2013, ICLR — 2014.')],'Kingma & Welling · Auto-Encoding Variational Bayes','https://arxiv.org/abs/1312.6114'),
s('gan',2014,'2014','Генеративное моделирование','GAN: обучаемый соперник','Можно ли научить генератор реализму без явного сравнения пикселей?','Генератор преобразует случайный код в образец. Дискриминатор учится отличать настоящие данные от сгенерированных. Его градиент становится сигналом для улучшения генератора.','Два потока — реальные и синтетические образцы — сходятся в дискриминаторе. Отдельная линия возвращает обучающий сигнал к генератору.','Дискриминатор обучается вместе с генератором: критерий качества постоянно меняется.',[
step('Построить два потока','Настоящий x поступает из данных. Синтетический G(z) создаётся из случайного z. Оба проходят через один дискриминатор D, который оценивает принадлежность к реальным данным.'),step('Обновить дискриминатор','На этом шаге генератор фиксирован. D должен повышать оценки реальных образцов и понижать оценки синтетических.',"\\max_D\\;\\begin{aligned}&\\mathbb E_x[\\log D(x)]\\\\&+\\mathbb E_z[\\log(1-D(G(z)))]\\end{aligned}"),step('Обновить генератор','Теперь веса D фиксированы, но производная проходит сквозь его вычисления к G. Часто используют non-saturating objective, чтобы получить более полезный градиент.',"\\min_G\\;-\\mathbb E_z[\\log D(G(z))]"),step('Почему это трудно','Игра может быть нестабильной. Генератор иногда находит небольшой набор убедительных образцов и теряет разнообразие — mode collapse. Реалистичность и покрытие распределения не одно и то же.')],'Goodfellow et al. · Generative Adversarial Networks','https://arxiv.org/abs/1406.2661'),
s('attention',2014,'2014–2015','Язык и контекст','Attention: извлекать нужное в нужный момент','Почему одного фиксированного вектора для всей фразы недостаточно?','В раннем Seq2Seq encoder сжимает вход для decoder. Attention даёт decoder доступ ко всем состояниям входа: на каждом шаге он строит новое взвешенное сочетание, подходящее для текущего выходного токена.','Две цепочки токенов и меняющийся веер связей между ними.','Контекст перестаёт быть одним неизменным контейнером.',[
step('Сохранить состояния входа','Encoder выдаёт последовательность h₁…hₙ. Вместо потери деталей в одном векторе модель сохраняет представление каждой позиции.'),step('Оценить релевантность','Текущее состояние decoder сравнивается с каждым состоянием encoder. Softmax превращает оценки в неотрицательные веса с суммой 1.',"\\alpha_{ti}=\\operatorname{softmax}_i\\!\\left(\\operatorname{score}(s_{t-1},h_i)\\right)"),step('Собрать контекст','Контекстный вектор — взвешенная сумма состояний входа. Он участвует в предсказании очередного токена. В схеме веса иллюстративные, не сняты с обученной модели.',"c_t=\\sum_i\\alpha_{ti}h_i"),step('Перейти к self-attention','Если запросы, ключи и значения получаются из одной последовательности, элементы могут уточнять друг друга. Эта идея станет центральной в Transformer.')],'Bahdanau, Cho & Bengio · Neural Machine Translation by Jointly Learning to Align and Translate','https://arxiv.org/abs/1409.0473'),
s('resnet',2015,'2015','Архитектуры глубины','ResNet: сохранить прямой путь','Почему просто добавить слоёв недостаточно?','Глубокие сети могут быть труднее оптимизировать, даже когда дополнительная глубина теоретически не должна мешать. Остаточный блок прибавляет к входу обучаемое изменение, сохраняя прямой путь для сигнала и градиента.','Стопка блоков с внешними светящимися обходными соединениями.','Слой учит поправку F(x), а не обязан заново строить всё преобразование.',[
step('Обычная последовательность','В обычной цепочке каждый блок полностью преобразует сигнал. Градиент последовательно умножается на производные всех преобразований.'),step('Добавить identity shortcut','Остаточный блок возвращает x + F(x). Если полезное изменение мало, блок может приблизиться к тождественному отображению через F(x) ≈ 0.',"y=x+F(x)"),step('Сохранить путь градиента','В производной появляется слагаемое I. Это помогает оптимизации, но не отменяет другие трудности. При смене размеров shortcut использует проекцию.',"\\frac{\\partial y}{\\partial x}=I+\\frac{\\partial F}{\\partial x}"),step('Распространить идею','Residual connections используются не только в CNN: они станут стандартной частью Transformer, diffusion-сетей и многих других архитектур.')],'He et al. · Deep Residual Learning for Image Recognition','https://arxiv.org/abs/1512.03385'),
s('rl',2016,'1988–2017','Обучение через действия','От отложенной награды к self-play','Как улучшать действия, если верного ответа для каждого шага нет?','TD-learning и Q-learning оценивают будущую полезность действий. Deep RL использует нейросети для представления состояний. AlphaGo соединяет нейросетевые policy/value-модели с поиском, а AlphaGo Zero обучается через игру с собой.','Доска Go, дерево поиска и замкнутый контур взаимодействия.','Политика, оценка состояния и поиск выполняют разные функции.',[
step('Цикл взаимодействия','Агент наблюдает s, выбирает a, получает r и следующее состояние s′. Цель — не только немедленная награда, но и ожидаемый будущий возврат.'),step('TD-ошибка связывает настоящее с будущим','Q-learning обновляет оценку действия через награду и оценку следующего состояния. Вклад будущего регулирует γ.',"\\begin{aligned}\\delta={}&r+\\gamma\\max_{a\\prime}Q(s\\prime,a\\prime)\\\\&-Q(s,a)\\end{aligned}"),step('Сеть и поиск дополняют друг друга','Policy подсказывает перспективные ходы, value оценивает позицию, поиск проверяет продолжения. DQN — 2015, AlphaGo против Lee Sedol — 2016, AlphaGo Zero — 2017.'),step('Self-play создаёт опыт','Противник становится частью процесса генерации обучающих данных. AlphaGo Zero не использует партии людей для обучения, но опирается на правила Go и заданный алгоритм.')],'Silver et al. · Mastering the game of Go without human knowledge','https://www.nature.com/articles/nature24270'),
s('transformer',2017,'2017','Язык и контекст','Transformer: вычислять связи напрямую','Как дать каждому токену доступ к удалённым частям контекста?','Transformer заменяет рекуррентную передачу состояния механизмом внимания. Self-attention смешивает информацию между позициями, feed-forward преобразует каждую позицию отдельно. Порядок задаётся позиционным представлением.','Стек attention-блоков с многоголовыми связями между токенами.','При обучении позиции можно обрабатывать параллельно; генерация следующего токена остаётся пошаговой.',[
step('Создать Q, K и V','Каждый токен превращается в три вектора: запрос, ключ и значение. Это разные обучаемые линейные проекции одного представления.',"\\begin{aligned}Q&=XW_Q\\\\K&=XW_K\\\\V&=XW_V\\end{aligned}"),step('Сравнить запросы с ключами','Матрица QKᵀ содержит оценки для всех пар токенов. Деление на √dₖ стабилизирует масштаб, softmax нормирует каждую строку.',"A=\\operatorname{softmax}\\!\\left(\\frac{QK^{\\mathsf T}}{\\sqrt{d_k}}+M\\right)"),step('Смешать значения, а не токены','AV создаёт новое представление каждой позиции. Несколько голов учат разные способы связывать контекст; их выходы объединяются и проецируются.',"\\operatorname{Attention}(Q,K,V)=AV"),step('Собрать полный блок','Residual connections и normalization окружают attention и feed-forward. Оригинальная модель содержит encoder и decoder; у decoder дополнительно есть causal self-attention и cross-attention к encoder.'),step('Понять границы','Полное attention строит N × N взаимодействий. Параллелизм обучения не означает параллельную авторегрессионную генерацию всей последовательности.')],'Vaswani et al. · Attention Is All You Need','https://arxiv.org/abs/1706.03762'),
s('bert',2018,'2018','Язык и контекст','BERT и GPT: разные задачи, общий фундамент','Что модель имеет право видеть при обучении?','BERT учится восстанавливать скрытые токены с доступом к левому и правому контексту. GPT предсказывает следующий токен, используя только предыдущие позиции. Маска внимания и обучающая цель создают разные режимы работы.','Две матрицы связей: полная двунаправленная и нижнетреугольная причинная.','Различие определяется доступным контекстом и задачей, а не «пониманием» против «творчества».',[
step('BERT: восстановить скрытое','Для входа «Кот [MASK] на ковре» модель использует слова с обеих сторон. Предобученные представления затем адаптируют к задачам. Оригинальный BERT также использовал next sentence prediction.'),step('GPT: продолжить последовательность','Для позиции t запрещён доступ к будущим токенам. При обучении многие позиции рассчитываются параллельно с causal mask; при генерации следующий токен добавляется к контексту.',"p(x_1,\\ldots,x_n)=\\prod_{t=1}^{n}p(x_t\\mid x_{<t})"),step('Маска — ограничение потока информации','На диаграмме строка — позиция запроса, столбец — доступная позиция контекста. Полная матрица BERT и треугольник GPT показывают именно разрешённые связи, а не фактические веса внимания.')],'Devlin et al. · BERT; Radford et al. · GPT','https://arxiv.org/abs/1810.04805'),
s('diffusion',2020,'2015 → 2020','Генеративное моделирование','Diffusion: научиться обращать разрушение','Как получить структуру, начав со случайного шума?','Прямой процесс постепенно зашумляет данные. Сеть получает шумный образец и номер шага, обучаясь предсказывать внесённый шум или связанную с ним величину. Генерация выполняет последовательность обратных обновлений.','Пять объёмных облаков: от случайных частиц к структурированному объекту.','На каждом обратном шаге используется одна и та же обученная сеть с разным временем.',[
step('Прямой процесс известен','На выбранном шаге t можно сразу построить xₜ из чистого x₀ и стандартного шума ε. Расписание ᾱₜ задаёт соотношение сигнала и шума.',"x_t=\\sqrt{\\bar\\alpha_t}\\,x_0+\\sqrt{1-\\bar\\alpha_t}\\,\\varepsilon"),step('Сеть учится предсказывать шум','Сеть εθ(xₜ,t) обучается на случайных шагах и образцах. В распространённой простой цели её предсказание сравнивается с реально добавленным ε.',"L_{\\mathrm{simple}}=\\mathbb E\\!\\left[\\left\\|\\varepsilon-\\varepsilon_\\theta(x_t,t)\\right\\|^2\\right]"),step('Генерация начинается с шума','Обратные шаги используют оценку сети и выбранный sampler. В DDPM переходы стохастические; другие samplers могут работать иначе. Это не однократное вычитание всего шума.'),step('От идеи к практическому качеству','2015: Sohl-Dickstein и коллеги формулируют диффузионное моделирование. 2020: DDPM Ho, Jain и Abbeel — важная веха. Анимация здесь иллюстрирует процесс и не является выводом обученной сети.')],'Ho, Jain & Abbeel · Denoising Diffusion Probabilistic Models','https://arxiv.org/abs/2006.11239'),
s('latent',2022,'2021 / 2022','Генеративное моделирование','Latent diffusion: считать в компактном пространстве','Нужно ли выполнять каждый дорогой шаг в пикселях?','Автоэнкодер сжимает изображение в латентное представление. Диффузионная модель работает в этом пространстве, а декодер возвращает результат в пиксели. Условие, например текст, направляет процесс через отдельный путь.','Большая пиксельная плоскость сжимается в компактный объём и разворачивается обратно.','Компрессия, генеративная динамика и текстовое условие — три разных компонента.',[
step('Сначала обучить представление','Encoder E переводит x в z, decoder D восстанавливает изображение. Автоэнкодер должен сохранить визуально важную информацию при меньшей размерности.'),step('Обучать diffusion на z','Шум добавляется к латентному коду, а сеть удаляет его там. Это снижает вычислительную стоимость по сравнению с обработкой полного изображения на каждом шаге.',"\\begin{aligned}z_0&=E(x)\\\\(z_t,t,c)&\\longmapsto\\varepsilon_\\theta(z_t,t,c)\\end{aligned}"),step('Подать условие отдельно','Текстовый encoder формирует c. Cross-attention связывает визуальные признаки с представлением текста. На инференсе image encoder не нужен: шум → denoiser → decoder.'),step('Соединить семейства моделей','VAE-подобное представление, diffusion и attention могут сосуществовать в одной системе. Это не три конкурирующие «версии одной нейросети». Работа: preprint 2021, CVPR 2022.')],'Rombach et al. · High-Resolution Image Synthesis with Latent Diffusion Models','https://arxiv.org/abs/2112.10752'),
s('multimodal',2023,'Современные подходы','Модели и системы','Одна модель — несколько источников сигнала','Что происходит поверх базового предобучения?','Большие корпуса дают широкие представления. Дообучение на инструкциях и обратной связи формирует поведение. Согласование разных модальностей позволяет связывать текст, изображение и звук; внешний цикл инструментов превращает модель в компонент агента.','Текст, изображение и звук сходятся в общий вычислительный центр.','Архитектура, обучающая цель и организация системы — разные уровни описания.',[
step('Предобучение строит основу','Предсказание или восстановление данных позволяет извлекать структуру без ручной разметки каждого ответа. Поведение после этого ещё не обязательно соответствует пользовательской инструкции.'),step('Адаптация задаёт поведение','Демонстрации инструкций, предпочтения и другие сигналы изменяют ответы модели. RLHF — один из подходов; не вся адаптация обязательно является reinforcement learning.'),step('Мультимодальность и инструменты','Модальности связываются обучаемыми encoder/projector-компонентами. Агент добавляет цикл «модель → действие → наблюдение». Это ещё не гарантия достоверности или успешного планирования.'),step('Подготовить переход к физике','До сих пор сигнал в основном извлекался из данных и взаимодействия. Но иногда у нас уже есть уравнение процесса. Его можно сделать частью обучения напрямую.')],'Концептуальное сравнение уровней; без обзора конкретных продуктов',''),
s('pinn',2019,'2017 / 2019 → Scientific ML','Данные и законы','Physics-informed: учиться в пределах возможного','Что, если кроме наблюдений известен закон природы?','PINN представляет поле нейросетью и учится одновременно по данным, уравнениям и условиям задачи. Разберём охлаждение квадратной пластины: почему одних наблюдений мало и как физика ограничивает возможные решения.','Трёхмерное температурное поле: высота и цвет обозначают температуру, золотые точки — синтетические измерения, белые — проверки уравнения. Меняйте время и скорость охлаждения в лаборатории.','Гладкая и правдоподобная картинка ещё не означает физически допустимое решение.',[
step("Горячая пластина, холодные края","Рассмотрим квадратную пластину: x и y от 0 до 1. Края удерживаются при нулевой температуре, а центр вначале нагрет сильнее. Коэффициент температуропроводности α = 0.3. Высота поверхности и её цвет показывают температуру — сама пластина не выгибается.","\\begin{aligned}u_t&=0.3(u_{xx}+u_{yy})\\\\u(x,y,0)&=\\sin(\\pi x)\\sin(\\pi y)\\end{aligned}"),
step("Сеть как непрерывное поле","Три входа — x, y, t — задают точку пространства и времени. Выход сети — температура. Autodiff вычисляет производные по этим входам. Белые точки показывают места проверки PDE: мы не задаём там правильную температуру, а проверяем согласованность производных.","r_\\theta=u_{\\theta,t}-0.3(u_{\\theta,xx}+u_{\\theta,yy})"),
step("Наблюдения и законы дополняют друг друга","Золотые точки — синтетические измерения из точного решения. Они ограничивают значения температуры. Белые точки ограничивают динамику через уравнение. Отдельно задаются начальное состояние и холодные края. Эти источники информации нельзя подменять друг другом.","L_d=\\frac1{N_d}\\sum_i|u_\\theta(x_i,y_i,t_i)-u_i|^2"),
step("Как выглядит обучение","Сеть вычисляет поле в точках данных и физических ограничений. Ошибки объединяются с весами, затем градиент обновляет параметры сети. Веса ограничений, выбор точек и оптимизация влияют на результат. Нулевая ошибка на небольшой выборке не гарантирует решение во всей области.","L=\\lambda_dL_d+\\lambda_rL_r+\\lambda_iL_i+\\lambda_bL_b"),
step("Эксперимент: нарушить физику","Ползунок β меняет скорость охлаждения учебного поля. Все варианты сохраняют холодные края и одинаковое начальное состояние. Но только β = α = 0.3 выполняет заданное уравнение. Карта справа показывает модуль невязки: красивая гладкая поверхность может быть физически неверной.","\\begin{aligned}u_\\beta&=\\sin(\\pi x)\\sin(\\pi y)e^{-2\\beta\\pi^2t}\\\\r_\\beta&=2\\pi^2(0.3-\\beta)u_\\beta\\end{aligned}"),
step("Прямая задача, обратная задача и границы метода","В прямой задаче α известно и ищется поле. В обратной α можно восстанавливать вместе с параметрами сети, если наблюдения достаточно информативны. Здесь показано аналитическое семейство, а не обученная PINN: ползунок лишь объясняет роль физического ограничения. Настоящие PINN могут испытывать трудности на жёстких и многомасштабных задачах.","u(x,y,t)=\\sin(\\pi x)\\sin(\\pi y)e^{-0.6\\pi^2t}")],'Raissi, Perdikaris & Karniadakis · 2017 / 2019','https://maziarraissi.github.io/PINNs/'),
s("llm",2020,"2018 → 2020-е","Язык как универсальный интерфейс","LLM: от продолжения текста к универсальной модели","Как одна модель решает задачи, которых не было в отдельном списке?","Большая языковая модель учится на разнообразных последовательностях. В генеративной LLM на основе decoder-only Transformer каждый шаг предсказывает следующий токен. Инструкция, примеры и контекст направляют поведение одной и той же модели.","Токены проходят через стек преобразований, превращаются в распределение продолжений и возвращаются в контекст. Высота столбиков — условные вероятности.","Обучение меняет веса. Инструкция и примеры в контексте меняют вход, обычно не меняя весов.",[
step("Текст становится последовательностью","Токен — элемент словаря: слово, часть слова, знак или иной фрагмент. Токенизация зависит от модели и языка. Затем идентификаторы заменяются обученными векторами, к которым добавляется информация о позиции. В схеме показаны условные фрагменты, не конкретный токенизатор.",""),
step("Предсказать следующее продолжение","Causal Transformer обрабатывает доступный префикс. Выходная проекция и softmax дают распределение по словарю. Выбор следующего токена может быть жадным или стохастическим. Затем токен добавляется к префиксу и процесс повторяется.","p_\\theta(x_{1:T})=\\prod_{t=1}^{T}p_\\theta(x_t\\mid x_{<t})"),
step("Предобучение и адаптация","Предобучение оптимизирует предсказание на большом корпусе. Дообучение на демонстрациях инструкций и предпочтениях формирует более полезное поведение. Это разные обучающие сигналы; адаптация не обязана использовать RL.","L_{\\mathrm{LM}}=-\\sum_t\\log p_\\theta(x_t\\mid x_{<t})"),
step("Задача задаётся контекстом","Инструкция, несколько примеров и нужные документы входят в контекст. In-context learning обычно не обновляет параметры сети. RAG добавляет найденные материалы перед генерацией, а не автоматически записывает их в веса. Размер контекста конечен.",""),
step("Разделить возможности и ограничения","Правдоподобное продолжение не гарантирует истинности. Модель может ошибаться, смешивать сведения и терять детали длинного контекста. Для вычислений, проверки источников и действий можно подключить внешние инструменты — это переход от модели к агентной системе.","")],"Brown et al. · Language Models are Few-Shot Learners, 2020","https://arxiv.org/abs/2005.14165"),
s("agents",2023,"2022 → современные системы","Финал · модели действуют","LLM-агент: модель внутри цикла действий","Что меняется, когда ответ модели становится следующим действием?","Агентная система соединяет LLM, состояние задачи, инструменты и управляющий цикл. Модель предлагает действие; программа проверяет и исполняет его; результат возвращается в контекст. Цикл продолжается до выполнения цели или условия остановки.","Орбитальная схема: цель и контекст, LLM, шлюз исполнения, инструмент и наблюдение. Световой пакет проходит замкнутый цикл.","Агентность — свойство организации системы. Вызов инструмента предлагает модель, а исполняет окружающая программа.",[
step("Задать цель и состояние","Система хранит задачу, доступные инструменты, текущие наблюдения и ограничения. План может уточняться после каждого шага. Рабочая память — состояние приложения или контекст; это не обязательно новые знания в весах модели.",""),
step("Предложить структурированное действие","LLM может вернуть имя инструмента и аргументы вместо конечного ответа. Например, для сравнения тепловых режимов — вызвать вычисление температуры с заданными координатами и временем. Запись вызова сама по себе ещё ничего не исполняет.",""),
step("Исполнить и получить наблюдение","Оркестратор проверяет аргументы и доступность операции, затем вызывает код, поиск или другой инструмент. Инструмент возвращает результат либо ошибку. Внешний текст — данные наблюдения; он не должен самовольно менять правила системы.",""),
step("Замкнуть цикл на конкретном примере","Цель: сравнить температуру центра пластины при t=0.1 и t=0.3. Инструмент вычисляет точные значения 0.553 и 0.169 для α=0.3. Модель получает числа, сравнивает их и формулирует ответ. Это учебный сценарий: внешняя LLM здесь не запускается.",""),
step("Проверить результат и остановиться","Остановка задаётся выполнением цели, лимитом шагов или передачей решения человеку. Ошибка инструмента может потребовать исправить аргументы, а не повторять тот же вызов бесконечно. Один агент уже образует такой цикл; несколько агентов — необязательное усложнение.","")],"Yao et al. · ReAct, 2022 / ICLR 2023","https://arxiv.org/abs/2210.03629")
];
